import unittest
import mock
from mock import patch
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_coam.pages.account_management import (UserAccountManagementPopup,
                                                               LocalUserAccountManagementTab,
                                                               ServiceAccountManagementTab)


class TestUserAccountManagementPopup(unittest.TestCase):

    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.user_account_management_popup = UserAccountManagementPopup()

    def test_open_user_account_management_popup(self):
        self.user_account_management_popup.click_enabled_element = mock.MagicMock()

        self.user_account_management_popup._open_user_account_management_popup()

        open_user_account_xpath = (By.XPATH, self.user_account_management_popup
                                   ._OPEN_USER_ACCOUNT_MANAGEMENT_POPUP_XPATH)
        self.user_account_management_popup.click_enabled_element.assert_called_with(open_user_account_xpath)

    def test_switch_to_local_user_account_management_tab(self):
        self.user_account_management_popup.click_enabled_element = mock.MagicMock()

        self.user_account_management_popup._switch_to_local_user_account_management_tab()

        switch_to_local_user_account_management_tab_xpath = (By.XPATH, self.user_account_management_popup
                                                             ._SWITCH_TO_LOCAL_USER_ACCOUNT_TAB_XPATH)
        self.user_account_management_popup.click_enabled_element\
            .assert_called_with(switch_to_local_user_account_management_tab_xpath)

    def test_switch_to_service_account_management_tab(self):
        self.user_account_management_popup.click_enabled_element = mock.MagicMock()

        self.user_account_management_popup._switch_to_service_account_management_tab()

        switch_to_service_account_management_tab_xpath = (By.XPATH, self.user_account_management_popup
                                                          ._SWITCH_TO_SERVICE_ACCOUNT_TAB_XPATH)
        self.user_account_management_popup.click_enabled_element\
            .assert_called_with(switch_to_service_account_management_tab_xpath)


class TestLocalUserAccountManagementTab(unittest.TestCase):

    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.local_user_account_tab = LocalUserAccountManagementTab()

    def test_change_username_for_bts_system_administrator_account(self):
        self.local_user_account_tab._open_user_account_management_popup = mock.MagicMock()
        self.local_user_account_tab._switch_to_local_user_account_management_tab = mock.MagicMock()
        self.local_user_account_tab._select_account_type_from_local_user_accounts_list = mock.MagicMock()
        self.local_user_account_tab._fill_empty_field = mock.MagicMock()
        self.local_user_account_tab._click_enabled_button = mock.MagicMock()
        self.local_user_account_tab._get_validation_status = mock.MagicMock()
        self.local_user_account_tab.disable_message_box = mock.MagicMock()

        self.local_user_account_tab.change_username_for_bts_system_administrator_account("Nemuadmin")
        self.local_user_account_tab._open_user_account_management_popup.assert_called_once()
        self.local_user_account_tab._switch_to_local_user_account_management_tab.assert_called_once()
        self.local_user_account_tab._select_account_type_from_local_user_accounts_list.assert_called_once()
        self.local_user_account_tab._fill_empty_field.assert_called_once()
        self.local_user_account_tab._click_enabled_button.assert_called()
        self.local_user_account_tab._get_validation_status.assert_called_once()

    def test_change_password_for_bts_system_administrator_account(self):
        self.local_user_account_tab._open_user_account_management_popup = mock.MagicMock()
        self.local_user_account_tab._switch_to_local_user_account_management_tab = mock.MagicMock()
        self.local_user_account_tab._select_account_type_from_local_user_accounts_list = mock.MagicMock()
        self.local_user_account_tab._fill_empty_field = mock.MagicMock()
        self.local_user_account_tab._click_enabled_button = mock.MagicMock()
        self.local_user_account_tab._get_validation_status = mock.MagicMock()

        self.local_user_account_tab.change_password_for_bts_system_administrator_account("nemuuser", "nemuuser")
        self.local_user_account_tab._open_user_account_management_popup.assert_called_once()
        self.local_user_account_tab._switch_to_local_user_account_management_tab.assert_called_once()
        self.local_user_account_tab._select_account_type_from_local_user_accounts_list.assert_called_once()
        self.local_user_account_tab._fill_empty_field.assert_called()
        self.local_user_account_tab._click_enabled_button.assert_called()
        self.local_user_account_tab._get_validation_status.assert_called_once()


class TestServiceAccountManagementTab(unittest.TestCase):

    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.service_account_tab = ServiceAccountManagementTab()

    def test_change_password_for_service_account(self):
        self.service_account_tab._open_user_account_management_popup = mock.MagicMock()
        self.service_account_tab._switch_to_service_account_management_tab = mock.MagicMock()
        self.service_account_tab._fill_empty_field = mock.MagicMock()
        self.service_account_tab._click_enabled_button = mock.MagicMock()
        self.service_account_tab._get_validation_status = mock.MagicMock()

        self.service_account_tab.change_password_for_service_account("test", "test", "new_test", "new_test")
        self.service_account_tab._open_user_account_management_popup.assert_called_once()
        self.service_account_tab._switch_to_service_account_management_tab.assert_called_once()
        self.service_account_tab._fill_empty_field.assert_called()
        self.service_account_tab._click_enabled_button.assert_called()
        self.service_account_tab._get_validation_status.assert_called_once()
